static std::wstring metaRuntime(){
 // Both older Quest Link and the renamed Horizon Link register this service.
 wchar_t command[32768]{};DWORD bytes=sizeof(command);if(RegGetValueW(HKEY_LOCAL_MACHINE,L"SYSTEM\\CurrentControlSet\\Services\\OVRService",L"ImagePath",RRF_RT_REG_SZ|RRF_RT_REG_EXPAND_SZ,nullptr,command,&bytes)!=ERROR_SUCCESS)return{};
 std::wstring exe=command;if(exe.starts_with(L'"')){auto end=exe.find(L'"',1);if(end==std::wstring::npos)return{};exe=exe.substr(1,end-1);}else{auto end=exe.find(L".exe");if(end!=std::wstring::npos)exe.resize(end+4);}
 auto manifest=std::filesystem::path(exe).parent_path()/L"oculus_openxr_64.json";std::error_code ec;return std::filesystem::is_regular_file(manifest,ec)?manifest.wstring():std::wstring{};
}

static VrPose pose(const XrPosef&p){return{{p.orientation.x,p.orientation.y,p.orientation.z,p.orientation.w},{p.position.x,p.position.y,p.position.z}};}
void VrSession::check(XrResult r,const char*operation){if(XR_FAILED(r)){char name[XR_MAX_RESULT_STRING_SIZE]{};if(instance)xrResultToString(instance,r,name);throw std::runtime_error(std::string(operation)+": "+(name[0]?name:std::to_string(r))+". Start wired Quest Link and check the PC's active OpenXR runtime.");}}
XrPath VrSession::path(const char*name){XrPath p;check(xrStringToPath(instance,name,&p),"OpenXR input path");return p;}
